<!-- Wordmark, from logo_status.svg. "Status" follows the text colour in dark mode.
     A row of uptime-strip bars sits in the free space left of "Status", under the "g" descender. -->
<script lang="ts">
  // 14 bars across x 34–746, sitting on the "Status" baseline (y≈404) at about its x-height.
  // Tops keep a 20 gap to the text above: "bangumi" ends at y≈209, the "g" descender (x≈563 on)
  // at y≈262.
  const BARS = 14, W = 36, GAP = 16, X0 = 34, BOTTOM = 404, DESCENDER_X = 563;
  const bars = Array.from({ length: BARS }, (_, i) => {
    const x = X0 + i * (W + GAP);
    return { x, top: x + W < DESCENDER_X ? 229 : 282 };
  });
</script>

